import { currentUser } from "@clerk/nextjs/server";
import type { User as ClerkUser } from "@clerk/nextjs/server";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Clerk owns sign-up/sign-in/session state. This maps the signed-in Clerk
// identity onto our own User record, creating or updating it in the local
// store on the way in (a stand-in for a real users table keyed by Clerk id).
function fromClerkUser(clerkUser: ClerkUser): User {
  const primaryEmail =
    clerkUser.emailAddresses.find(
      (e) => e.id === clerkUser.primaryEmailAddressId
    )?.emailAddress ?? clerkUser.emailAddresses[0]?.emailAddress ?? "";
  const name =
    [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") ||
    clerkUser.username ||
    primaryEmail;
  const createdAt = new Date(clerkUser.createdAt).toISOString().slice(0, 10);

  const existing = users.find((u) => u.id === clerkUser.id);
  if (existing) {
    existing.email = primaryEmail;
    existing.name = name;
    return existing;
  }

  const record: User = { id: clerkUser.id, email: primaryEmail, name, createdAt };
  users.push(record);
  return record;
}

export async function getCurrentUser(): Promise<User | undefined> {
  const clerkUser = await currentUser();
  if (!clerkUser) return undefined;
  return fromClerkUser(clerkUser);
}

